class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        l, r = 0, len(numbers) - 1              # 一头一尾
        while l < r:
            s = numbers[l] + numbers[r]
            if s == target:
                return [l + 1, r + 1]           # 题目的下标从 1 开始
            if s < target:                      # 太小：numbers[l] 和谁配都不够
                l += 1
            else:                               # 太大：numbers[r] 和谁配都太大
                r -= 1
        return []

