class Solution {
    public int[] twoSum(int[] numbers, int target) {
        int l = 0, r = numbers.length - 1;      // 一头一尾
        while (l < r) {
            int s = numbers[l] + numbers[r];
            if (s == target) {
                return new int[]{l + 1, r + 1}; // 题目的下标从 1 开始
            }
            if (s < target) {                   // 太小：numbers[l] 和谁配都不够
                l++;
            } else {                            // 太大：numbers[r] 和谁配都太大
                r--;
            }
        }
        return new int[0];
    }
}

