class Solution {
    public int removeDuplicates(int[] nums) {
        int slow = 1;                                   // nums[0..slow-1] 是去重后的结果
        for (int fast = 1; fast < nums.length; fast++) {    // fast 往前扫每一个数
            if (nums[fast] != nums[slow - 1]) {         // 和结果的最后一个不一样：是新数
                nums[slow] = nums[fast];
                slow++;
            }
        }
        return slow;
    }
}

